from collections import deque

def minimumOperations(grid):
    m, n = len(grid), len(grid[0])
    INF = float('inf')

    # Left side: 1-cells on "black" squares ((i + j) even) that touch another 1
    left, adj = [], {}
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and (i + j) % 2 == 0:
                nb = [(i + di) * n + (j + dj)
                      for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1))
                      if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 1]
                if nb:
                    u = i * n + j
                    left.append(u)
                    adj[u] = nb

    match_l = {u: -1 for u in left}   # left cell -> matched right cell
    match_r = {}                      # right cell -> matched left cell
    dist = {}

    def bfs():
        # Layer the graph starting from the free left vertices (one Hopcroft-Karp phase)
        q = deque()
        for u in left:
            if match_l[u] == -1:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = INF
        found = False
        while q:
            u = q.popleft()
            for v in adj[u]:
                w = match_r.get(v, -1)
                if w == -1:
                    found = True
                elif dist[w] == INF:
                    dist[w] = dist[u] + 1
                    q.append(w)
        return found

    def dfs(root, ptr):
        # Iterative DFS for an augmenting path that follows the BFS layers
        stack = [root]
        while stack:
            u = stack[-1]
            if ptr[u] < len(adj[u]):
                v = adj[u][ptr[u]]
                ptr[u] += 1
                w = match_r.get(v, -1)
                if w == -1:
                    for x in stack:                 # augment along the path
                        vx = adj[x][ptr[x] - 1]
                        match_l[x] = vx
                        match_r[vx] = x
                    return True
                if dist[w] == dist[u] + 1:
                    stack.append(w)
            else:
                dist[u] = INF                       # dead end
                stack.pop()
        return False

    res = 0   # size of the maximum matching = minimum vertex cover (König)
    while bfs():
        ptr = {u: 0 for u in left}
        for u in left:
            if match_l[u] == -1 and dfs(u, ptr):
                res += 1
    return res
